"""Layer 15 MLP down-projection, component 1602: a "small / limited amount" detector.

The component is positive on words that say a quantity is small, low or limited
("small", "tiny", "limited", "fewer", "less", "low", "short", "reduced", "only", "under",
"below", "<", "<="), and most strongly on "than" after "less" or "smaller" ("less than").
It is negative on words of excess or increase ("high", "higher", "larger", "increase",
"exceeds", "too", "extra", "beyond"), and it is switched off after "not" ("not only",
"not limited to"). Most of its variance is in context, so this word list explains only a
small share; it is a readable rule, not a full account.
"""

READS = ()

SMALL = {}  # word -> typical activation for a small or limited amount
for words, value in [
    ("small smaller smallest tiny modest limited fewer lesser shorter narrow mini restricted", 6),
    ("less low reduced reduce reduces reduction decreases minimal minimum limit limitations", 4),
    ("lower short little weak weaker petite brief", 3),
    ("only below half young min simple simpler", 2),
    ("under few just", 1),
    ("小 少 低 只 弱 仅 有限 短 只能", 3),  # the same ideas in Chinese
]:
    for word in words.split():
        SMALL[word] = value

EXCESS = set(  # words of excess or increase: the component goes negative
    "high higher larger bigger greater increase increased increases exceeds exceed elevated "
    "excess excessive too multiple extra additional beyond".split()
)
COMPARATIVE_SMALL = {"less", "smaller", "lower"}
COMPARATIVE_LARGE = {"more", "larger", "greater", "bigger", "higher"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word == "than" and prev in COMPARATIVE_SMALL:
        return carry, 9.0  # "less than", "smaller than"
    if word == "than" and prev in COMPARATIVE_LARGE:
        return carry, -1.0  # "more than", "larger than"
    if prev in ("not", "nor", "no"):
        return carry, 0.0  # negated: "not only", "not limited to"
    if word in ("<", "≤", "<="):
        return carry, 2.5 if word == "<" else 5.5  # "<" is often a code bracket
    if word in SMALL:
        return carry, float(SMALL[word])
    if word in EXCESS:
        return carry, -1.0
    if word == "more":
        return carry, -0.3
    return carry, 0.0

"""Time- and effort-saving detector for layers.15.mlp.down_proj component 1618.

What the component does: when its activation is positive, it pushes the next-token
distribution toward words about making things easy, quick or automatic ("automatic",
"simplify", "convenient", "effortless", "shortcut", "time-saving"). It is switched on
inside text about saving time or effort: the words "save"/"saves" and their synonyms,
"easier", "simplify", "convenient", "lazy", "hassle", and verbs like "make ... easier",
"reduce", "avoid", "skip", "without". The strongest activations come at the object of a
save-verb: "save [time]", "saves [you] work", "save [thousands]".

This program reads only the tokens so far, with no model in it. It predicts:
- a baseline near the component's mean (-0.05) on most tokens;
- +1.7 on an ease word (saving, convenience, simplicity, automation);
- +1.4 on a verb of making or avoiding work ("make", "reduce", "avoid", "without");
- +6.5 on a time/effort object (time, effort, money, work, you, ...) that comes
  right after a save-word, or one word after it, in the same document
  ("save time", "saves you time").
Save-words themselves count as ease words, so "save" gets +1.7 and "save time" gets
+1.7 on "save" and +6.5 on "time".

Limits: the component's activation is mostly a diffuse signal that these word lists do
not capture, so this explains only a small share of its variance. A token-by-token table
of the most frequent words would explain a little more but is not a concept.
"""

READS = ()

EASE_WORDS = {
    "save", "saves", "saving", "saved", "savings", "saver", "time-saving", "time-saver",
    "automate", "automated", "automation", "automatic", "automatically", "automates",
    "streamline", "streamlined", "simplify", "simplifies", "simplified", "simplifying",
    "simpler", "simplest", "simplicity", "simple", "simply",
    "easy", "easier", "easiest", "easily", "ease",
    "convenient", "convenience", "conveniently", "effortless", "effortlessly", "handy",
    "shortcut", "shortcuts", "lazy", "hassle", "quicker", "efficient", "efficiently",
    "facilitate", "facilitates",
    "省", "节省", "简化", "自动化", "懒", "方便", "便捷", "便利", "轻松", "省事", "免",
}
WORK_VERBS = {
    "make", "makes", "making", "made", "reduce", "reduces", "reducing", "eliminate",
    "avoid", "skip", "omit", "prevent", "without", "minimize",
}
SAVE_WORDS = {"save", "saves", "saving", "saved", "savings"}
OBJECTS = {
    "time", "effort", "money", "work", "you", "thousands", "hassle", "steps", "energy",
    "hours", "minutes", "space", "trouble", "cost", "costs",
}
BASELINE = -0.05
EASE_VALUE = 1.7
WORK_VALUE = 1.4
OBJECT_VALUE = 6.5


def word(token_string):
    return token_string.strip().lower()


def step(carry, prefix, upstream):
    """This component's activation at the newest token of `prefix`."""
    current = word(prefix.token_strings[-1])
    value = BASELINE
    if current in EASE_WORDS:
        value = EASE_VALUE
    elif current in WORK_VERBS:
        value = WORK_VALUE
    if current in OBJECTS:
        # Is a save-word one or two tokens back, in the same document?
        for back in (2, 3):
            if prefix.position >= back - 1 and prefix.document_ids[-back] == prefix.document_ids[-1]:
                if word(prefix.token_strings[-back]) in SAVE_WORDS:
                    value = OBJECT_VALUE
    return carry, float(value)

"""Layer 15 MLP down_proj, component 1620: "where is it placed" detector.

The component fires in passive or copular descriptions of a physical thing's location or
placement, and it pushes the next word toward location talk ("located in", "placed on").
Its activation is positive on:
  * a placement verb or participle (located, situated, mounted, placed, stored ...): strongest;
  * a locative preposition (in, on, at, within ...) directly after such a word ("located in"),
    and mildly the "the" after it;
  * the be-verb that leads into a passive or copular description (was, is, been, are ...),
    weaker when the subject is an expletive or a pronoun ("There is", "This is", "it was");
  * release, publication and delivery participles (released, published, shipped, filed) and
    other "held / found / kept" participles, at a middle level.
Everything else is predicted as 0. Values are in the component's own activation units.
"""

READS = ()

PLACEMENT = {
    " located", " situated", " mounted", " disposed", " positioned", " placed", " scattered",
    " stored", " inserted", " deposited", " lying", " attached", " installed", " buried",
    " embedded", " displayed", " housed", " nestled", " sits", " 放在", "位于", "坐落",
}
PASSIVE_VERB = {
    " held", " found", " kept", " put", " hidden", " released", " published", " aired",
    " shipped", " filed", " delivered", " posted", " sent", " submitted", " based",
}
BE = {" be", " been", " being", " was", " were", " is", " are", " am", " été", " être", " sont", " étaient", " são", " essere", " sido"}
EXPLETIVE = {" There", "There", " there", " Here", " here", " This", "This", " this", " it", " It", " I", " we", " We"}
LOCATIVE = {" in", " on", " at", " within", " inside", " into", " onto", " under", " near", " along", " by"}
ARTICLE = {" the", " a", " an"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1] else ""
    if cur in PLACEMENT:
        return carry, 5.0
    if cur in PASSIVE_VERB:
        return carry, 2.0
    if cur in BE:
        return carry, 1.5 if prev in EXPLETIVE else 3.0
    if cur in LOCATIVE:
        if prev in PLACEMENT:
            return carry, 4.5
        if prev in BE or prev in PASSIVE_VERB:
            return carry, 2.5
        return carry, 0.0
    if cur in ARTICLE and prev in LOCATIVE:
        return carry, 0.5
    return carry, 0.0

"""Layer 15, MLP hidden unit 1624 (this component is that unit's output direction).

Mostly a small, noisy, slightly negative value (about -0.05). It goes positive when a
code comment or docstring is opened: the marker " //", " #", " /*" or a triple quote
(larger when the marker follows indentation or a space), and at a citation opener "[@"
or ",[". Everything else gets the baseline. Token-level rules only: the rest of its
variance is context-dependent and is not captured here.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

BASELINE = -0.05
COMMENT_OPENERS = {" //", " #", " /*", ' """', "//", "/*"}
CITATION_OPENERS = {"[@", ",["}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    if tok in COMMENT_OPENERS:
        before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        return carry, (2.8 if before.strip() == "" else 1.5)
    if tok in CITATION_OPENERS:
        return carry, 2.0
    return carry, BASELINE

"""Layer 15 MLP hidden unit 1630 (the down_proj component 1630), as a word rule.

The component mostly reads one MLP hidden unit (about 60% of its input weight is on
unit 1630, the rest is spread thinly), so its activation tracks that unit's value. Its output pushes
the next-token distribution toward verb and participle continuations ("posted",
"announced", "generated") and away from "的 + person noun" continuations ("的父亲",
"的妻子").

Where it is large and positive, the current token is usually a word for a person or
people: third-person pronouns and possessives (he, she, they, his, her, their, 's), person
nouns (father, sister, someone), or a word right after a verb of perceiving or knowing
(saw, heard, see, knew, understand). Most of those words are only mildly positive, and
the largest values depend on context this rule cannot see.

This program predicts a small value on those words and 0 elsewhere:
- 0.3 for a people pronoun or possessive; 0.15 for a WordNet person noun;
- 0.5 for a perception or knowing verb itself;
- 0.55 for a token right after one (within the same document).
It explains only a little variance (about 0.3% on eval), and its end-to-end effect on the
model's output is about that of switching the component off.
"""
from wordnet import categories

PEOPLE_PRONOUNS = set(
    "he she they him her them his hers their theirs himself herself themselves "
    "someone anyone everyone others people 's ’s".split()
)
PERCEIVING = set(
    "see saw seen sees hear heard hears watch watched know knew understand learn "
    "meet met follow".split()
)

READS = ()


def _word(text):
    return text.strip().lower()


def _is_person_noun(word):
    return word.isalpha() and word.isascii() and "noun.person" in categories(word)


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    value = 0.0
    if word in PEOPLE_PRONOUNS:
        value += 0.3
    elif _is_person_noun(word):
        value += 0.15
    if word in PERCEIVING:
        value += 0.5
    if before in PERCEIVING:
        value += 0.55
    return carry, float(value)

"""Layer 15 MLP down-projection, component 1638.

What it responds to: negative activations on restrictive / "nothing more than"
words ("only", "just", "merely", "simply", "mere", "bare", "plain", "raw", "alone",
"except", "without", "excluding", "rather", "instead") and on "unqualified" words
("whole", "entire", "full", "original", "directly", "itself"). The largest dip is on
" the" directly after one of the restrictive words ("just the", "only the",
"without the"). The word right after a restrictive word is mildly negative too.

This is a small part of what the component does. Most of its activation is
small, context-dependent noise that no word rule captures (a per-token lookup
explains about 0% of held-out variance), so this program explains under 1% of
the variance. Its values are the least-squares fit on about 8k training rows.
"""

READS = ()

RESTRICTIVE = {
    "only", "just", "merely", "simply", "mere", "bare", "plain", "raw", "alone",
    "except", "without", "excluding", "rather", "instead",
}
UNQUALIFIED = {"whole", "entire", "full", "original", "directly", "itself"}

ON_RESTRICTIVE = -0.66   # the word itself
ON_UNQUALIFIED = -0.56   # the word itself
THE_AFTER_RESTRICTIVE = -2.2
AFTER_RESTRICTIVE = -0.38  # any other token right after a restrictive word
AFTER_UNQUALIFIED = -0.17  # any other token right after an unqualified word


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    prev = ""
    if len(prefix.token_ids) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = _word(prefix.token_strings[-2])
    if prev in RESTRICTIVE and word == "the":
        value = THE_AFTER_RESTRICTIVE
    elif prev in RESTRICTIVE:
        value = AFTER_RESTRICTIVE
    elif prev in UNQUALIFIED:
        value = AFTER_UNQUALIFIED
    elif word in RESTRICTIVE:
        value = ON_RESTRICTIVE
    elif word in UNQUALIFIED:
        value = ON_UNQUALIFIED
    else:
        value = 0.0
    return carry, float(value)

"""Layer-15 MLP neuron 1661 (its down_proj component), predicted from the current token alone.

The neuron's activation is near zero on most tokens and has no clean trigger. Its
strongest positive responses come on words that introduce what something should,
would or alternatively be, or what an expression evaluates, outputs, or is written
or interpreted as (should, would, expected, alternatively, instead, equivalent,
evaluates, outputs, written, parsed). Its strongest negative responses come on
markup, tool-call and JSON-like literals ({", arguments, </tool_call>, </think>),
and on month names.

This program reads only the newest token and returns a fixed value per word class.
"""

READS = ()

EXPECT = {"should", "would", "expect", "expects", "expected", "supposed", "intended",
          "instead", "alternatively", "cannot", "must"}
EVALUATE = {"evaluate", "evaluates", "equivalent", "interpreted", "parsed", "parse",
            "output", "outputs", "returns", "written", "write", "raise", "throw",
            "assert", "prints", "becomes", "rounds"}
MARKUP = {'{"', "arguments", "</tool_call>", "</think>", "<think>", "user", "ignore",
          "eof", "ago", "born", "finished"}
MONTHS = {"january", "february", "march", "april", "may", "june", "july", "august",
          "september", "october", "november", "december"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in EXPECT:
        value = 0.3
    elif word in EVALUATE:
        value = 0.25
    elif word in MARKUP:
        value = -0.33
    elif word in MONTHS:
        value = -0.16
    else:
        value = 0.0
    return carry, value
